UPDATE truss.feed_member m SET delivery_ordinal = NULL WHERE m.source_epoch = $1::pg_catalog.text AND m.feed_profile = $2::pg_catalog.text AND m.original_writer_xid = pg_catalog.pg_current_xact_id_if_assigned() RETURNING m.source_epoch, m.feed_profile, m.original_writer_xid::pg_catalog.text AS original_writer_xid, m.registration_address::pg_catalog.text AS registration_address, m.delivery_ordinal::pg_catalog.text AS delivery_ordinal